/**
 * @description Schedulable and Batchable class to purge old integration logs.
 * It deletes logs based on their level: non-ERROR logs after 30 days, 
 * and ERROR logs after 180 days.
 */
public class LogPurgeJob implements Schedulable, Database.Batchable<sObject> {

    /**
     * No-argument constructor required by the requirements.
     */
    public LogPurgeJob() {
    }

    /**
     * Implementation of Schedulable.execute.
     * When the job is triggered by the scheduler, it initiates the batch job.
     * 
     * @param sc The SchedulableContext.
     */
    public void execute(SchedulableContext sc) {
        Database.executeBatch(new LogPurgeJob());
    }

    /**
     * Implementation of Batchable.start.
     * Defines the scope of records to be deleted using a QueryLocator.
     * 
     * @param bc The BatchableContext.
     * @return A QueryLocator containing the records matching the purge criteria.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime thirtyDaysAgo = DateTime.now().addDays(-30);
        DateTime oneEightyDaysAgo = DateTime.now().addDays(-180);

        // We use (Level__c != 'ERROR' OR Level__c = null) to correctly include 
        // records where Level__c is blank, as SOQL != comparison excludes nulls.
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :thirtyDaysAgo AND (Level__c != 'ERROR' OR Level__c = null))
               OR (CreatedDate < :oneEightyDaysAgo AND Level__c = 'ERROR')
        ]);
    }

    /**
     * Implementation of Batchable.execute.
     * Deletes the records in the current batch scope.
     * 
     * @param bc The BatchableContext.
     * @param scope The list of FB_Integration_Log__c records to delete.
     */
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        if (!scope.isEmpty()) {
            // Using allOrNone=false to ensure that one failing record (e.g. due to a lock 
            // or trigger) doesn't prevent the rest of the batch from being purged.
            Database.delete(scope, false);
        }
    }

    /**
     * Implementation of Batchable.finish.
     * 
     * @param bc The BatchableContext.
     */
    public void finish(Database.BatchableContext bc) {
        // No additional post-processing required for this purge job.
    }

    /**
     * Schedules the LogPurgeJob to run every day at 02:00.
     * 
     * @return The Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        // Cron expression for 02:00 AM every day: 0 seconds, 0 minutes, 2 hours, every day of month, every month, any day of week.
        String cronExpression = '0 0 2 * * ?';
        String jobName = 'Log purge (nightly)';
        return System.schedule(jobName, cronExpression, new LogPurgeJob());
    }
}
