public class ContactPhoneCleanup {
    /**
     * Normalizes phone numbers for a given list of Contact IDs.
     * 
     * Removes all characters from the Phone field except for digits and the '+' sign.
     * Only contacts that currently have a phone number are updated.
     * 
     * @param contactIds A list of Contact IDs to be processed (up to 200).
     * @return A Map where the key is the Id of a contact that failed to save, 
     *         and the value is its first error message.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errors = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errors;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // We must query the contacts to check their current Phone value, 
        // as the requirement specifies that contacts without a phone are left out.
        for (Contact con : [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds]) {
            if (String.isNotBlank(con.Phone)) {
                // Remove all characters that are NOT a digit (0-9) or a plus sign (+)
                // In a regex character class [^...], the '+' is treated as a literal.
                con.Phone = con.Phone.replaceAll('[^0-9+]', '');
                contactsToUpdate.add(con);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // Use partial success (allOrNone = false) so that one failure does not block the rest.
            Database.SaveResult[] results = Database.update(contactsToUpdate, false);

            for (Integer i = 0; i < results.size(); i++) {
                Database.SaveResult sr = results[i];
                if (!sr.isSuccess()) {
