import { LightningElement, api } from 'lwc';

/**
 * statusListbox component
 * A single-select listbox following the WAI-ARIA listbox pattern with aria-activedescendant.
 */
export default class StatusListbox extends LightningElement {
    /** Accessible name of the list */
    @api label = '';

    /** Array of { value, label } */
    @api options = [];

    _value = '';

    /** The selected value */
    @api
    get value() {
        return this._value;
    }

    set value(val) {
        this._value = val;
        this.updateActiveOption(val);
    }

    /** The index of the currently "active" (focused via aria-activedescendant) option */
    activeOptionIndex = 0;

    /** Returns the ID of the active option for aria-activedescendant */
    get activeOptionId() {
        if (this.options.length === 0) {
            return '';
        }
        return `option-${this.activeOptionIndex}`;
    }

    /** Maps options to include necessary rendering properties */
    get renderedOptions() {
        return this.options.map((option, index) => ({
            id: `option-${index}`,
            label: option.label,
            value: option.value,
            isSelected: option.value === this._value
        }));
    }

    /** Updates the active index based on the provided value */
    updateActiveOption(val) {
        if (this.options.length === 0) {
            this.activeOptionIndex = 0;
            return;
        }
        const index = this.options.findIndex(opt => opt.value === val);
        if (index !== -1) {
            this.activeOptionIndex = index;
        } else {
            // If nothing is selected (or value not in options), default to first option
            this.activeOptionIndex = 0;
        }
    }

    /** Initialize active option on component load */
    connectedCallback() {
        this.updateActiveOption(this._value);
    }

    /**
     * Handles keyboard navigation on the listbox.
     * Uses aria-activedescendant to manage focus visually/aurally without moving DOM focus.
     */
    handleKeyDown(event) {
        const { key } = event;
        let newIndex = this.activeOptionIndex;

        switch (key) {
            case 'ArrowDown':
                newIndex = Math.min(this.activeOptionIndex + 1, this.options.length - 1);
                event.preventDefault();
                break;
            case 'ArrowUp':
                newIndex = Math.max(this.activeOptionIndex - 1, 0);
                event.preventDefault();
                break;
            case 'Home':
                newIndex = 0;
                event.preventDefault();
                break;
            case 'End':
                newIndex = this.options.length - 1;
                event.preventDefault();
                break;
            case 'Enter':
            case ' ':
                if (this.options.length > 0) {
                    this.selectOption(this.options[this.activeOptionIndex].value);
                }
                event.preventDefault();
                break;
            default:
                // Do not prevent default for other keys (like Tab)
                return;
        }

        this.activeOptionIndex = newIndex;
    }

    /** Handles selection via mouse click */
    handleOptionClick(event) {
        const value = event.currentTarget.dataset.value;
        const index = this.options.findIndex(opt => opt.value === value);
        if (index !== -1) {
            this.activeOptionIndex = index;
            this.selectOption(value);
        }
    }

    /** 
     * Selects an option, updates internal state, and dispatches change event.
     * @param {any} value The value to select.
     */
    selectOption(value) {
        if (value !== this._value) {
            this._value = value;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: value }
            }));
        }
    }
}
