public inherited sharing class FamilyService {
    /**
     * Links parents to children in NPSP.
     * 
     * For each pair in the input map, a relationship is created where the child is the 
     * npe4__Contact__c and the parent is the npe4__RelatedContact__c with Type 'Parent'.
     * Due to NPSP's 'List Setting' reciprocal method, NPSP will automatically create 
     * the reciprocal relationship record (e.g., Son/Daughter/Child) in the opposite direction.
     * 
     * @param parentIdByChildId Map where key is Child Contact Id and value is Parent Contact Id.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> allIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null) {
                allIds.add(childId);
                allIds.add(parentId);
            }
        }

        if (allIds.isEmpty()) {
            return;
        }

        // Identify existing relationships to ensure idempotency and avoid duplicates.
        // We check both directions by using a direction-agnostic key.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allIds OR npe4__RelatedContact__c IN :allIds
        ]) {
            if (rel.npe4__Contact__c != null && rel.npe4__RelatedContact__c != null) {
                existingPairKeys.add(getPairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            }
        }

        List<npe4__Relationship__c> newRels = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null) {
                String pairKey = getPairKey(childId, parentId);
                if (!existingPairKeys.contains(pairKey)) {
                    newRels.add(new npe4__Relationship__c(
                        npe4__Contact__c = childId,
                        npe4__RelatedContact__c = parentId,
                        npe4__Type__c = 'Parent',
                        npe4__Status__c = 'Current'
                    ));
                    // Prevent adding the same pair twice if the input map contains both (A, B) and (B, A)
                    existingPairKeys.add(pairKey);
                }
            }
        }

        if (!newRels.isEmpty()) {
            insert newRels;
