public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {
    /**
     * Executes at the end of a DML operation.
     * If any Opportunity IDs were collected by the Trigger Action,
     * it enqueues a single Queueable job and clears the collection.
     */
    public void execute(FinalizerHandler.Context context) {
        if (!TA_Opportunity_CollectForErpSync.idsToSync.isEmpty()) {
            System.enqueueJob(new OpportunityErpSyncJob(TA_Opportunity_CollectForErpSync.idsToSync));

            // Clear the collection so subsequent DMLs in the same transaction 
            // do not include these IDs.
            TA_Opportunity_CollectForErpSync.idsToSync.clear();
        }
    }
}
